#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
vector<long long> factorials, invFactorials;

long long add_mod(long long a, long long b) {
    return (a + b) % MOD;
}

long long sub_mod(long long a, long long b) {
    return ((a - b) % MOD + MOD) % MOD;
}

long long mul_mod(long long a, long long b) {
    return (a * b) % MOD;
}

long long fast_pow(long long base, long long exp) {
    long long result = 1;
    long long cur = base % MOD;
    while (exp > 0) {
        if (exp & 1) {
            result = mul_mod(result, cur);
        }
        cur = mul_mod(cur, cur);
        exp >>= 1;
    }
    return result;
}

void precompute_factorials() {
    factorials.resize(1000000);
    invFactorials.resize(1000000);
    factorials[0] = 1;
    for (int i = 1; i < 1000000; i++) {
        factorials[i] = mul_mod(factorials[i - 1], i);
    }
    invFactorials[999999] = fast_pow(factorials[999999], MOD - 2);
    for (int i = 999998; i >= 0; i--) {
        invFactorials[i] = mul_mod(invFactorials[i + 1], i + 1);
    }
}

long long calculate_combination(int n, int k) {
    if (k > n || k < 0) return 0;
    return mul_mod(factorials[n], mul_mod(invFactorials[k], invFactorials[n - k]));
}

long long calculate_power(int base, long long exp) {
    long long sum = 0;
    for (int i = 0; i < base; i++) {
        long long term = mul_mod(fast_pow(base - i, exp), calculate_combination(base, i));
        if (i % 2 == 0) {
            sum = add_mod(sum, term);
        } else {
            sum = sub_mod(sum, term);
        }
    }
    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    precompute_factorials();

    int n, k;
    cin >> n >> k;

    if (k == 0) {
        cout << factorials[n] << "\n";
        return 0;
    }
    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }

    int remaining = n - k;
    long long assignWays = calculate_power(remaining, n);
    long long pickWays = calculate_combination(n, remaining);
    long long total = mul_mod(assignWays, pickWays);
    cout << mul_mod(total, 2) << "\n";

    return 0;
}

